package io.github.ilyaslabs.foodstack.identity.core.application;

import java.util.EnumSet;

import io.github.ilyaslabs.foodstack.identity.api.Role;
import io.github.ilyaslabs.foodstack.identity.core.IdentityProperties;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;

import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.core.annotation.Order;

/**
 * Creates the first administrator from {@code foodstack.identity.bootstrap-admin} (generated by
 * {@code install.sh}) when no account with that email exists yet, so a fresh install can log in.
 */
public class BootstrapAdmin {

    private static final Log logger = LogFactory.getLog(BootstrapAdmin.class);

    private final UserService users;

    private final IdentityProperties.BootstrapAdmin settings;

    public BootstrapAdmin(UserService users, IdentityProperties properties) {
        this.users = users;
        this.settings = properties.getBootstrapAdmin();
    }

    @EventListener(ApplicationReadyEvent.class)
    @Order(0)
    public void createIfMissing() {
        String email = this.settings.getEmail();
        if (email == null || email.isBlank() || this.settings.getPassword() == null) {
            return;
        }
        if (this.users.emailExists(email)) {
            return;
        }
        this.users.create(new NewUser(email, this.settings.getPassword(), this.settings.getDisplayName(),
                EnumSet.of(Role.ADMIN)), "bootstrap");
        logger.info("Created the first administrator account " + email);
    }
}
